// This script is generated by Gemini
using TMPro;
using UnityEngine;

// Hayatta kalma süresini ve toplanan yaprak sayısını tutar.
// Oyun sırasında skor panelinde gösterir, oyun bitince Game Over ekranına
// güncel skoru ve en iyi skoru yazar.
public class ScoreManager : MonoBehaviour
{
    public static ScoreManager Instance { get; private set; }

    const string BestScoreKey = "BestScore";

    [Header("Oyun sırasındaki skor paneli")]
    [Tooltip("Sadece oyun oynanırken görünür; menüler açıkken gizlenir")]
    [SerializeField] GameObject scoreboardPanel;
    [SerializeField] TMP_Text timeText;
    [SerializeField] TMP_Text leafText;
    
    // NEW: Trash Bag UI text
    [SerializeField] TMP_Text bagText;

    [Header("Game Over ekranındaki yazılar")]
    [SerializeField] TMP_Text currentScoreText;
    [SerializeField] TMP_Text bestScoreText;

    [Header("Puanlama & Çanta")]
    [SerializeField] int pointsPerSecond = 1;
    [SerializeField] int pointsPerLeaf = 5;
    
    // NEW: Bag Capacity limits
    public int maxBagCapacity = 15;
    public int currentBagLoad = 0;

    float survivalTime;
    int leaves;

    public int Score => Mathf.FloorToInt(survivalTime) * pointsPerSecond + leaves * pointsPerLeaf;
    public int BestScore => PlayerPrefs.GetInt(BestScoreKey, 0);

    void Awake()
    {
        Instance = this;
    }

    void OnEnable()  => GameMenu.OnGameOver += HandleGameOver;
    void OnDisable() => GameMenu.OnGameOver -= HandleGameOver;

    void Start()
    {
        survivalTime = 0f;
        leaves = 0;
        currentBagLoad = 0;
        UpdateScoreboard();
    }

    void Update()
    {
        if (scoreboardPanel != null && scoreboardPanel.activeSelf != GameMenu.IsPlaying)
            scoreboardPanel.SetActive(GameMenu.IsPlaying);

        if (!GameMenu.IsPlaying) return;

        survivalTime += Time.deltaTime;
        UpdateScoreboard();
    }

    // NEW: Returns how many leaves were successfully added before the bag got full
    public int AddLeaves(int amount)
    {
        if (!GameMenu.IsPlaying || amount <= 0) return 0;
        
        if (currentBagLoad >= maxBagCapacity) return 0; // Bag is totally full

        // Calculate how much space is left in the bag
        int spaceLeft = maxBagCapacity - currentBagLoad;
        int pickedUp = Mathf.Min(amount, spaceLeft);

        currentBagLoad += pickedUp;
        leaves += pickedUp;
        UpdateScoreboard();

        return pickedUp;
    }

    // NEW: Called by the Dumpster to clear out the encumbrance
    public void EmptyBag()
    {
        currentBagLoad = 0;
        UpdateScoreboard();
    }

    void HandleGameOver()
    {
        int final = Score;
        int best = BestScore;

        if (final > best)
        {
            best = final;
            PlayerPrefs.SetInt(BestScoreKey, best);
            PlayerPrefs.Save();
        }

        if (currentScoreText != null) currentScoreText.text = "Score: " + final;
        if (bestScoreText != null)    bestScoreText.text    = "Best: " + best;
    }

    void UpdateScoreboard()
    {
        int seconds = Mathf.FloorToInt(survivalTime);
        if (timeText != null) timeText.text = $"Time: {seconds / 60:00}:{seconds % 60:00}";
        if (leafText != null) leafText.text = "Leaves: " + leaves;
        
        // NEW: Update Bag UI
        if (bagText != null) 
        {
            bagText.text = $"Bag: {currentBagLoad} / {maxBagCapacity}";
            if (currentBagLoad >= maxBagCapacity) bagText.color = Color.red; // Warn the player
            else bagText.color = Color.white;
        }
    }
}